package com.gathin.tvhome;
import android.content.*;
import android.database.ContentObserver;
import android.graphics.*;
import android.graphics.drawable.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
/** Optional owner-supplied previews. Queries only while Home is visible; artwork loads for bound cards. */
final class ContentPreviewShelf {
 private final MainActivity a;private final FrameLayout panel;private final TextView title;private final RecyclerView cards;private final SharedPreferences prefs;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor(),art=Executors.newFixedThreadPool(2);
 private final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<String,Bitmap>(3*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};
 private ContentPreviewData.Snapshot data=new ContentPreviewData.Snapshot();private String pkg="",rendered="";private final List<Future<?>> artTasks=new ArrayList<>();private boolean active,closed,observing,entering;private int generation;private PreviewAdapter adapter;
 private final Runnable query=this::load;private final ContentObserver observer=new ContentObserver(handler){public void onChange(boolean self){schedule();}};
 private final SharedPreferences.OnSharedPreferenceChangeListener listener=(p,k)->{if(k!=null&&(k.startsWith("content_preview_")||AppLock.LOCKS.equals(k)))refresh();};
 ContentPreviewShelf(MainActivity a,FrameLayout root){this.a=a;prefs=a.getSharedPreferences(Config.SETTINGS_NAME,0);panel=new FrameLayout(a);panel.setVisibility(View.GONE);GradientDrawable bg=new GradientDrawable();bg.setColor(0x77101620);bg.setCornerRadius(dp(12));bg.setStroke(dp(.5f),0x22FFFFFF);panel.setBackground(bg);panel.setPadding(dp(8),dp(5),dp(8),dp(5));title=GlassDialog.text(a,"",11);panel.addView(title,new FrameLayout.LayoutParams(-1,dp(18)));cards=new RecyclerView(a);cards.setLayoutManager(new LinearLayoutManager(a,RecyclerView.HORIZONTAL,false));cards.setItemAnimator(null);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,dp(89));cp.topMargin=dp(19);panel.addView(cards,cp);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(118));lp.leftMargin=dp(58);lp.rightMargin=dp(58);root.addView(panel,lp);prefs.registerOnSharedPreferenceChangeListener(listener);}
 private int dp(float v){return SettingsSheet.dp(a,v);}
 void start(){active=true;refresh();}void stop(){active=false;entering=false;generation++;handler.removeCallbacksAndMessages(null);observe(false);for(Future<?> task:artTasks)task.cancel(true);artTasks.clear();panel.setVisibility(View.GONE);cards.setAdapter(null);adapter=null;rendered="";}
 void focused(String value){if(value==null)value="";if(!value.equals(pkg)){pkg=value;render();}}
 void permissionChanged(){refresh();}
 private void refresh(){boolean enabled=active&&prefs.getBoolean(ContentPreviewData.ENABLED,false);observe(enabled);render();if(enabled)schedule();}
 private void observe(boolean enabled){if(enabled==observing)return;observing=enabled;try{if(enabled){a.getContentResolver().registerContentObserver(Uri.parse("content://android.media.tv/channel"),true,observer);a.getContentResolver().registerContentObserver(ContentPreviewData.PROGRAMS,true,observer);}else a.getContentResolver().unregisterContentObserver(observer);}catch(SecurityException|IllegalArgumentException ignored){}}
 private void schedule(){if(closed||!active)return;handler.removeCallbacks(query);handler.postDelayed(query,350);}
 private void load(){if(closed||!active)return;int token=++generation;worker.execute(()->{ContentPreviewData.Snapshot result=ContentPreviewData.load(a);handler.post(()->{if(closed||!active||token!=generation)return;data=result;render();});});}
 private void render(){if(closed)return;boolean show=active&&a.checkSelfPermission(ContentPreviewData.PERMISSION)==android.content.pm.PackageManager.PERMISSION_GRANTED&&prefs.getBoolean(ContentPreviewData.ENABLED,false)&&ContentPreviewData.appEnabled(a,pkg)&&!AppLock.locked(a,pkg);List<ContentPreviewData.Program> programs=new ArrayList<>();Set<String> hidden=prefs.getStringSet(ContentPreviewData.HIDDEN,Collections.emptySet());for(ContentPreviewData.Channel c:data.app(pkg))if(!hidden.contains(String.valueOf(c.id)))for(ContentPreviewData.Program p:c.programs)if(programs.size()<12)programs.add(p);
  if(!show||programs.isEmpty()){if(active&&cards.hasFocus())a.focusPreviewDock();panel.setVisibility(View.GONE);cards.setAdapter(null);adapter=null;rendered="";return;}
  String label=pkg;try{label=String.valueOf(a.getPackageManager().getApplicationLabel(a.getPackageManager().getApplicationInfo(pkg,0)));}catch(Exception ignored){}title.setText(label+" · Content-Vorschau");FrameLayout.LayoutParams lp=(FrameLayout.LayoutParams)panel.getLayoutParams();lp.topMargin=dp(prefs.getInt(ContentPreviewData.Y,200));panel.setLayoutParams(lp);panel.setVisibility(View.VISIBLE);StringBuilder key=new StringBuilder(pkg);for(ContentPreviewData.Program p:programs)key.append(p.id).append(p.title).append(p.poster).append(p.intent);if(adapter!=null&&key.toString().equals(rendered))return;rendered=key.toString();adapter=new PreviewAdapter(programs);cards.setAdapter(adapter);
 }
 boolean enterFromDock(KeyEvent event,boolean dock){if(event.getKeyCode()!=KeyEvent.KEYCODE_DPAD_UP)return false;if(entering&&event.getAction()==KeyEvent.ACTION_UP){entering=false;return true;}if(!dock||panel.getVisibility()!=View.VISIBLE||adapter==null||adapter.items.isEmpty())return false;if(event.getAction()==KeyEvent.ACTION_DOWN){entering=true;RecyclerView.ViewHolder holder=cards.findViewHolderForAdapterPosition(0);if(holder!=null)holder.itemView.requestFocus();}return true;}
 private final class Holder extends RecyclerView.ViewHolder {final ImageView image;final TextView label;Holder(LinearLayout box,ImageView image,TextView label){super(box);this.image=image;this.label=label;}}
 private final class PreviewAdapter extends RecyclerView.Adapter<Holder>{final List<ContentPreviewData.Program> items;PreviewAdapter(List<ContentPreviewData.Program> items){this.items=items;}public int getItemCount(){return items.size();}
  public Holder onCreateViewHolder(ViewGroup parent,int type){LinearLayout box=new LinearLayout(a);box.setId(View.generateViewId());box.setOrientation(LinearLayout.VERTICAL);box.setFocusable(true);box.setFocusableInTouchMode(true);box.setClickable(true);box.setPadding(dp(3),dp(3),dp(3),dp(2));box.setBackground(SettingsSheet.rowBackground(a));RecyclerView.LayoutParams lp=new RecyclerView.LayoutParams(dp(134),-1);lp.setMargins(0,0,dp(7),0);box.setLayoutParams(lp);ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);box.addView(image,new LinearLayout.LayoutParams(-1,dp(64)));TextView label=GlassDialog.text(a,"",9);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setDuplicateParentStateEnabled(true);label.setTextColor(SettingsSheet.ink(0xFFE4E9F1,0xFF171C23));label.setPadding(dp(3),dp(3),0,0);box.addView(label,new LinearLayout.LayoutParams(-1,-2));return new Holder(box,image,label);}
  public void onBindViewHolder(Holder h,int position){ContentPreviewData.Program p=items.get(position);h.label.setText(p.title);h.itemView.setContentDescription(p.title);h.itemView.setTag(p.poster);h.image.setImageDrawable(new AppGlyph("video"));Bitmap saved=cache.get(p.poster);if(saved!=null)h.image.setImageBitmap(saved);else if(!p.poster.isEmpty())loadArt(h,p.poster);
   h.itemView.setOnClickListener(v->{if(AppLock.locked(a,p.pkg)){Intent launch=a.getPackageManager().getLeanbackLaunchIntentForPackage(p.pkg);if(launch!=null)AppLock.launch(a,launch);return;}Intent target=ContentPreviewData.target(a,p);if(target==null)target=a.getPackageManager().getLeanbackLaunchIntentForPackage(p.pkg);if(target==null)return;try{AppLock.launch(a,target);}catch(ActivityNotFoundException|SecurityException e){Toast.makeText(a,R.string.not_available,Toast.LENGTH_SHORT).show();}});
   h.itemView.setOnKeyListener((v,key,event)->{int at=h.getBindingAdapterPosition();if((key==KeyEvent.KEYCODE_DPAD_LEFT&&at==0)||(key==KeyEvent.KEYCODE_DPAD_RIGHT&&at==items.size()-1))return true;if(key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)a.focusPreviewDock();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP){if(event.getAction()==KeyEvent.ACTION_UP)a.findViewById(R.id.btnDesign).requestFocus();return true;}return false;});h.itemView.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN)v.requestFocus();return false;});}
 }
 private void loadArt(Holder holder,String source){if(closed)return;artTasks.removeIf(Future::isDone);artTasks.add(art.submit(()->{Bitmap b=null;HttpURLConnection request=null;try{Uri uri=Uri.parse(source);InputStream raw;String scheme=uri.getScheme();if("content".equals(scheme))raw=a.getContentResolver().openInputStream(uri);else if("https".equals(scheme)||"http".equals(scheme)){request=(HttpURLConnection)new URL(source).openConnection();request.setConnectTimeout(4000);request.setReadTimeout(4000);if(request.getResponseCode()!=200||request.getContentLengthLong()>2*1024*1024)throw new IOException();raw=request.getInputStream();}else return;
   if(raw==null)return;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=raw){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(closed||Thread.currentThread().isInterrupted()||bytes.size()+n>2*1024*1024)throw new IOException();bytes.write(buffer,0,n);}}byte[] encoded=bytes.toByteArray();BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(encoded,0,encoded.length,o);if(o.outWidth<1||o.outHeight<1)throw new IOException();o.inSampleSize=1;while(o.outWidth/o.inSampleSize>384||o.outHeight/o.inSampleSize>216)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;b=BitmapFactory.decodeByteArray(encoded,0,encoded.length,o);
  }catch(Exception|OutOfMemoryError ignored){}finally{if(request!=null)request.disconnect();}Bitmap result=b;handler.post(()->{if(closed){if(result!=null)result.recycle();return;}if(result!=null){cache.put(source,result);if(active&&source.equals(holder.itemView.getTag()))holder.image.setImageBitmap(result);}});}));}
 void close(){closed=true;stop();prefs.unregisterOnSharedPreferenceChangeListener(listener);worker.shutdownNow();art.shutdownNow();cache.evictAll();}
}
